season=Path('src/game-engine/season.ts').read_text(encoding='utf-8')
season=replace_once(season,'import { DEFAULT_TRAINING_PLAN, applyTrainingDay, type TrainingPlan } from "./training";','import { DEFAULT_TRAINING_PLAN, applyTrainingDay, suggestedTrainingPlan, type TrainingPlan } from "./training";','training import')
season=replace_once(season,'import { createClubDynamics, evolveClubDynamics, hydrateClubDynamics, latestClubTrend, type ClubDynamicsState } from "./club-dynamics";','import { createClubDynamics, evolveClubDynamics, hydrateClubDynamics, latestClubTrend, type ClubDynamicsState } from "./club-dynamics";\nimport { createGamePreferences, hydrateGamePreferences, type GamePreferences } from "./game-preferences";','preferences import')
season=replace_once(season,'  clubDynamics:ClubDynamicsState;\n  championClubId?:string;','  clubDynamics:ClubDynamicsState;\n  preferences:GamePreferences;\n  championClubId?:string;','state preferences')
season=replace_once(season,'clubDynamics:createClubDynamics()});','clubDynamics:createClubDynamics(),preferences:createGamePreferences()});','create preferences')
season=replace_once(season,'if(!parsed.trainingPlan)parsed.trainingPlan=DEFAULT_TRAINING_PLAN;','if(!parsed.trainingPlan)parsed.trainingPlan=DEFAULT_TRAINING_PLAN;parsed.preferences=hydrateGamePreferences(parsed.preferences);','hydrate preferences')
season=replace_once(season,'  if(state.career?.status!=="Sem clube")applyTrainingDay(club,state.trainingPlan??DEFAULT_TRAINING_PLAN);','  const trainingPlan=state.preferences?.responsibilities.training==="Adjunto"?suggestedTrainingPlan(club):(state.trainingPlan??DEFAULT_TRAINING_PLAN);\n  if(state.career?.status!=="Sem clube")applyTrainingDay(club,trainingPlan);','delegated training')
season=replace_once(season,'return coordinateSeasonCalendars(processMarketRound({...state,league,lineupIds:selection.lineupIds,benchIds:selection.benchIds,livingWorld,mediaWorld,advancedWorld,worldLeagues}));','return coordinateSeasonCalendars(processMarketRound({...state,league,lineupIds:selection.lineupIds,benchIds:selection.benchIds,trainingPlan,livingWorld,mediaWorld,advancedWorld,worldLeagues}));','persist delegated training')

anchor='export function setMatchdayRole(state:SeasonState,playerId:string,role:MatchdayRole):SeasonState'
helper='''export function updateGamePreferences(state:SeasonState,preferences:GamePreferences):SeasonState{return{...state,preferences:hydrateGamePreferences(preferences)};}\n\nexport function applyConfiguredMediaDelegation(state:SeasonState):SeasonState{\n if(state.preferences?.responsibilities.pressConferences!=="Adjunto")return state;\n let next=state;for(const session of pendingMediaSessions(next.mediaWorld,next.competitionId)){next=delegateMediaSessionToAssistant(next,session.id).state;}return next;\n}\n\nfunction assistantSelectionScore(player:LeaguePlayer){return player.overall*5+player.condition*1.5-player.fatigue*2+(player.form??5)*3;}\nfunction assistantPick(players:LeaguePlayer[]){\n const sorted=[...players].sort((a,b)=>assistantSelectionScore(b)-assistantSelectionScore(a)),used=new Set<string>(),chosen:LeaguePlayer[]=[];\n const take=(positions:string[],count:number)=>{for(const player of sorted){if(chosen.length>=11||count<=0)break;if(!used.has(player.id)&&positions.includes(player.position)){chosen.push(player);used.add(player.id);count--;}}};\n take(["GOL"],1);take(["ZAG"],2);take(["LD","LE"],2);take(["VOL","MC","MEI"],3);take(["PD","PE","ATA","MEI"],3);\n for(const player of sorted){if(chosen.length>=11)break;if(!used.has(player.id)){chosen.push(player);used.add(player.id);}}return chosen.slice(0,11);\n}\nexport function applyConfiguredMatchdaySelection(state:SeasonState,cupMatchId?:string):SeasonState{\n if(state.preferences?.responsibilities.matchSelection!=="Adjunto")return state;const club=getSelectedClub(state),eligible=cupMatchId?new Set(worldMatchEligiblePlayerIds(state,cupMatchId)):undefined,available=club.players.filter(player=>player.injuryDays===0&&(eligible?eligible.has(player.id):player.suspensionMatches===0));if(available.length<11)return state;const xi=assistantPick(available),used=new Set(xi.map(player=>player.id)),benchSize=worldMatchdayRules(state,cupMatchId).benchSize,bench=available.filter(player=>!used.has(player.id)).sort((a,b)=>assistantSelectionScore(b)-assistantSelectionScore(a)).slice(0,Math.min(benchSize,Math.max(0,available.length-11)));const league=cloneLeague(state.league),nextClub=league.clubs.find(current=>current.id===state.selectedClubId)!;nextClub.players.forEach(player=>refreshStatus(player,xi.some(x=>x.id===player.id),bench.some(x=>x.id===player.id)));return{...state,league,lineupIds:xi.map(player=>player.id),benchIds:bench.map(player=>player.id)};\n}\n\n'''
if anchor not in season: raise SystemExit('missing helper anchor')
season=season.replace(anchor,helper+anchor,1)

pattern=r'export function advanceCalendarDay\(state:SeasonState\):CalendarAdvanceResult\{.*?\n\nexport function playCurrentCupMatch'
new_advance='''export function advanceCalendarDay(state:SeasonState):CalendarAdvanceResult{\n const prepareMedia=(current:SeasonState,context:MediaMatchContext)=>({...current,mediaWorld:mediaBeforeMatch(current.mediaWorld,current.competitionId,getSelectedClub(current),current.currentRound,current.baseSeed,context)});\n const prepareClubMatch=(current:SeasonState,context:MediaMatchContext,cupMatchId?:string)=>{let next=prepareMedia(current,context);next=applyConfiguredMatchdaySelection(next,cupMatchId);next=applyConfiguredMediaDelegation(next);return next;};\n const routeFor=(next:SeasonState,matchKey:string,fallback:CalendarRoute)=>pendingMediaSessions(next.mediaWorld,next.competitionId).some(session=>session.matchKey===matchKey&&session.format==="Coletiva pré-jogo")?"media":fallback;\n const nat=todayNationalFixture(state.nationalCareer,state.currentDate);if(nat){let next=prepareMedia(state,nationalMediaContext(state,nat));next=applyConfiguredMediaDelegation(next);return{state:next,route:routeFor(next,nat.id,"national"),reason:`${nat.homeName} × ${nat.awayName}: compromisso da seleção.`};}\n const cup=getTodayUserCupMatch(state);if(cup){const context=cupMediaContext(state,cup.match.id);if(context){const next=prepareClubMatch(state,context,cup.match.id);return{state:next,route:routeFor(next,cup.match.id,"matchday"),reason:`${cup.tournament.definition.shortName}: ${cup.match.stage}.`};}}\n const leagueMatch=getTodayUserFixture(state);if(leagueMatch){const next=prepareClubMatch(state,leagueMediaContext(state,leagueMatch));return{state:next,route:routeFor(next,leagueMatch.id,"matchday"),reason:"Dia de jogo: coletiva e preparação da partida."};}\n const current=state.currentDate??state.league.fixtures.find(f=>!f.played)?.date??`${state.year}-01-01`,nextDate=addIsoDays(current,1),dayNumber=Math.max(1,Math.floor((new Date(`${nextDate}T12:00:00Z`).getTime()-new Date(`${state.year}-01-01T12:00:00Z`).getTime())/86400000)+1),advanced=advanceSeasonDay({...state,currentDate:nextDate},dayNumber);let next={...advanced,nationalCareer:hydrateNationalCareer(advanced.nationalCareer,advanced.league,advanced.baseSeed,advanced.year,advanced.livingWorld.managerReputation,advanced.currentRound)};\n const n=todayNationalFixture(next.nationalCareer,next.currentDate);if(n){next=prepareMedia(next,nationalMediaContext(next,n));next=applyConfiguredMediaDelegation(next);return{state:next,route:routeFor(next,n.id,"national"),reason:`Compromisso da seleção: ${n.homeName} × ${n.awayName}.`};}\n const c=getTodayUserCupMatch(next);if(c){const ctx=cupMediaContext(next,c.match.id);if(ctx){next=prepareClubMatch(next,ctx,c.match.id);return{state:next,route:routeFor(next,c.match.id,"matchday"),reason:`${c.tournament.definition.shortName}: ${c.match.stage}.`};}}\n const l=getTodayUserFixture(next);if(l){next=prepareClubMatch(next,leagueMediaContext(next,l));return{state:next,route:routeFor(next,l.id,"matchday"),reason:"Dia de jogo: preparação da partida."};}\n const pending=next.livingWorld.inbox.find(event=>event.unread&&!event.resolved);if(pending?.kind==="Diretoria")return{state:next,route:"club",reason:`A diretoria precisa de você: ${pending.title}.`};if(pending)return{state:next,route:"inbox",reason:`Há uma decisão pendente: ${pending.title}.`};return{state:next,route:null,reason:"Dia avançado. Nenhuma decisão obrigatória surgiu."};\n}\n\nexport function playCurrentCupMatch'''
season,count=re.subn(pattern,new_advance,season,count=1,flags=re.S)
if count!=1: raise SystemExit('advanceCalendarDay replacement failed')
Path('src/game-engine/season.ts').write_text(season,encoding='utf-8')

live=Path('src/app/live-match-view.tsx').read_text(encoding='utf-8')
live=replace_once(live,'export default function LiveMatchView({session,home,away,onChange,onFinish}:{session:LiveMatchState;home:LeagueClub;away:LeagueClub;onChange:(next:LiveMatchState)=>void;onFinish:(session:LiveMatchState)=>void}){','export default function LiveMatchView({session,home,away,defaultSpeed,assistantTeamTalks,showStaffAdvice,onChange,onFinish}:{session:LiveMatchState;home:LeagueClub;away:LeagueClub;defaultSpeed:MatchSpeed;assistantTeamTalks:boolean;showStaffAdvice:boolean;onChange:(next:LiveMatchState)=>void;onFinish:(session:LiveMatchState)=>void}){','live props')
live=replace_once(live,' const [running,setRunning]=useState(false),[speed,setSpeed]=useState<MatchSpeed>("normal"),[outId,setOutId]=useState(""),[inId,setInId]=useState("");',' const [running,setRunning]=useState(false),[speed,setSpeed]=useState<MatchSpeed>(defaultSpeed),[outId,setOutId]=useState(""),[inId,setInId]=useState("");','default speed')
insert='''\n useEffect(()=>{\n  if(!assistantTeamTalks||session.phase!=="halftime"||session.teamTalk)return;const goalsFor=session.userSide==="home"?session.homeGoals:session.awayGoals,goalsAgainst=session.userSide==="home"?session.awayGoals:session.homeGoals,talk:TeamTalk=goalsFor<goalsAgainst?"Cobrar":goalsFor>goalsAgainst?"Acalmar":"Incentivar";onChange(setTeamTalk(session,talk));\n },[assistantTeamTalks,session,onChange]);\n'''
